<?php
require_once 'includes/config.php';require_admin();$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['grade'])) {verify_csrf();try{if(!srms_consume_operation($dbh,'grading.band.save'))throw new RuntimeException('This grading band change was already submitted.');$id=(int)($_POST['id']??0);$grade=strtoupper(trim($_POST['grade']??''));$min=(float)($_POST['min_percentage']??0);$max=(float)($_POST['max_percentage']??0);$remark=trim($_POST['remark']??'');$order=(int)($_POST['sort_order']??0);if(!preg_match('/^[A-Z0-9+\-]{1,10}$/',$grade)||$min<0||$max>100||$min>$max||$remark==='')throw new RuntimeException('Enter a valid grade, range from 0 to 100, and remark.');$q=$dbh->prepare($id?'UPDATE grading_bands SET grade=:g,min_percentage=:mi,max_percentage=:ma,remark=:r,sort_order=:o WHERE id=:id':'INSERT INTO grading_bands(grade,min_percentage,max_percentage,remark,sort_order) VALUES(:g,:mi,:ma,:r,:o)');$data=[':g'=>$grade,':mi'=>$min,':ma'=>$max,':r'=>$remark,':o'=>$order];if($id)$data[':id']=$id;$q->execute($data);audit_log($dbh,'GRADING_BAND_SAVE','Grade '.$grade.' range '.$min.'-'.$max);$msg='Grading band saved.';}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Could not save grading band. Check for duplicate grade names.';}}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete_id'])){verify_csrf();if(srms_consume_operation($dbh,'grading.band.delete')){$q=$dbh->prepare('DELETE FROM grading_bands WHERE id=:id');$q->execute([':id'=>(int)$_POST['delete_id']]);audit_log($dbh,'GRADING_BAND_DELETE','Deleted grading band '.(int)$_POST['delete_id']);}header('Location: manage-grading.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$dbh->prepare('SELECT * FROM grading_bands WHERE id=:id');$q->execute([':id'=>(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$dbh->query('SELECT * FROM grading_bands ORDER BY sort_order,min_percentage DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grading System | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-responsive.css"><link rel="stylesheet" href="css/srms-modernization.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid"><h2>Grading System</h2><p>Configure the grade bands used on report cards and analytics.</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading"><strong><?= $edit?'Edit grading band':'Add grading band'?></strong></div><div class="panel-body"><form method="post" class="row"><?=csrf_field()?><?=srms_operation_field('grading.band.save')?><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="col-sm-2 form-group"><label>Grade</label><input name="grade" maxlength="10" required class="form-control" value="<?=e($edit['grade']??'')?>"></div><div class="col-sm-2 form-group"><label>Minimum %</label><input type="number" min="0" max="100" step="0.01" name="min_percentage" required class="form-control" value="<?=e($edit['min_percentage']??'0')?>"></div><div class="col-sm-2 form-group"><label>Maximum %</label><input type="number" min="0" max="100" step="0.01" name="max_percentage" required class="form-control" value="<?=e($edit['max_percentage']??'100')?>"></div><div class="col-sm-4 form-group"><label>Remark</label><input name="remark" maxlength="100" required class="form-control" value="<?=e($edit['remark']??'')?>"></div><div class="col-sm-2 form-group"><label>Order</label><input type="number" name="sort_order" class="form-control" value="<?=e($edit['sort_order']??'0')?>"></div><div class="col-sm-12"><button class="btn btn-primary">Save band</button> <a href="manage-grading.php" class="btn btn-default">Clear</a></div></form></div></div><div class="panel panel-default"><div class="panel-body table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Grade</th><th>Range</th><th>Remark</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['grade'])?></td><td><?=e($r['min_percentage'].'% - '.$r['max_percentage'].'%')?></td><td><?=e($r['remark'])?></td><td><?=$r['sort_order']?></td><td><a class="btn btn-xs btn-primary" href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this grade band?')"><?=csrf_field()?><?=srms_operation_field('grading.band.delete')?><input type="hidden" name="delete_id" value="<?=$r['id']?>"><button class="btn btn-xs btn-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table><p class="text-muted">Avoid overlapping ranges and ensure all percentages from 0 to 100 are covered.</p></div></div></div></main></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
